#include <stdio.h>
#include <string.h>

/* Provided by the candidate in solution.c */
const char *asil_for(int severity, int exposure, int controllability);

int main(void)
{
    int severity, exposure, controllability;

    while (scanf(" S%d E%d C%d", &severity, &exposure, &controllability) == 3) {
        const char *result = asil_for(severity, exposure, controllability);

        if (result == NULL) {
            printf("(null)\n");
        } else if (strcmp(result, "QM") == 0) {
            printf("QM\n");
        } else {
            printf("ASIL %s\n", result);
        }
    }
    return 0;
}
